-- Keep these corrections separate from the compact catalog rows above so an
-- encoding-sensitive whole-line rewrite cannot damage neighboring text.
catalog.strings.zh.day = '日属性';
catalog.strings.zh.help_day = '/oddcast day [目标] | /oc day [目标] - 选择符合当前瓦纳迪尔日属性的最强可用法术。';
catalog.strings.ja.language_explain = '設定画面の表示言語を変更します。文字化け防止のため、ゲーム内チャットは英語で表示されます。魔法名は変更しません。';
catalog.strings.zh.language_explain = '更改设置界面的显示语言。为避免乱码，游戏聊天消息仍使用英语。法术名称保持不变。';

-- New UI surfaces remain usable while translations catch up: every supported
-- locale receives the English text for keys it has not translated yet.
for _, code in ipairs(catalog.order) do
    for key, value in pairs(catalog.strings.en) do
        if catalog.strings[code][key] == nil then catalog.strings[code][key] = value end
    end
end

return catalog;
